/**
 * What the quality set of EmbeddingGemma 2 holds: the image subjects, the spoken sentences, the
 * plan of every file the generator writes, the manifest's shape and the command line. Pure data and
 * pure functions — the GPU work is `generate.ts`.
 *
 * The set is generated by Karume's own pipelines (Anima, MOSS-Image and SBV2), so it needs no
 * outside material: 16 everyday subjects drawn by two image generators (near-duplicates across two
 * styles) and 8 Japanese sentences spoken by four SBV2 speakers.
 */

/** The manifest's format tag. */
export const MANIFEST_FORMAT = "karume-embeddinggemma2-quality-set/1";

/** One image of the manifest. */
export type ImageItem = {
  /** Relative to the set's directory: `images/<name>.png`. */
  readonly file: string;
  /** A plain English sentence naming the subject. */
  readonly caption: string;
  /** `<mirror>/<model id>`. */
  readonly generator: string;
  /** The prompt given to the generator. */
  readonly prompt: string;
  readonly seed: number;
};

/** One clip of the manifest. */
export type AudioItem = {
  /** Relative to the set's directory: `audio/<name>.wav`. */
  readonly file: string;
  /** The sentence spoken. */
  readonly transcript: string;
  /** `sbv2-jvnv/<speaker>`. */
  readonly generator: string;
  /** The WAV file's own rate (the generator's native rate — nothing is resampled). */
  readonly sampleRate: number;
};

export type QualitySetManifest = {
  readonly format: typeof MANIFEST_FORMAT;
  readonly images: readonly ImageItem[];
  readonly audio: readonly AudioItem[];
};

/** An image size both image generators accept (each side a multiple of 16, at least 512). */
export type ImageShape = { readonly width: number; readonly height: number };

const SQUARE: ImageShape = { width: 1024, height: 1024 };
const LANDSCAPE: ImageShape = { width: 1216, height: 832 };
const WIDE: ImageShape = { width: 1344, height: 768 };
const PORTRAIT: ImageShape = { width: 832, height: 1216 };

/** One subject: a file-name slug, the subject as a lower-case phrase, and the size it is drawn at. */
export type Subject = {
  readonly name: string;
  readonly phrase: string;
  readonly shape: ImageShape;
};

/**
 * The 16 subjects, drawn by both image generators at the same size and seed. Neutral, everyday
 * content only — no people, no named characters.
 */
export const SUBJECTS: readonly Subject[] = [
  { name: "fox", phrase: "a red fox sitting in fresh snow", shape: SQUARE },
  { name: "cat", phrase: "a tabby cat sleeping on a wooden windowsill", shape: LANDSCAPE },
  { name: "ramen", phrase: "a bowl of ramen with a boiled egg and green onions", shape: SQUARE },
  { name: "pancakes", phrase: "a stack of pancakes with blueberries and syrup", shape: PORTRAIT },
  { name: "bicycle", phrase: "a red bicycle leaning against a brick wall", shape: LANDSCAPE },
  { name: "locomotive", phrase: "a steam locomotive crossing a stone bridge", shape: WIDE },
  {
    name: "mountains",
    phrase: "a snowy mountain range above a calm lake at sunrise",
    shape: WIDE,
  },
  { name: "waterfall", phrase: "a waterfall in a mossy forest", shape: LANDSCAPE },
  { name: "lighthouse", phrase: "a lighthouse on a rocky cliff by the sea", shape: PORTRAIT },
  { name: "cabin", phrase: "a small wooden cabin in a pine forest", shape: SQUARE },
  {
    name: "tools",
    phrase: "a hammer, a wrench and a screwdriver on a workbench",
    shape: LANDSCAPE,
  },
  { name: "storm", phrase: "a lightning storm over a wheat field at night", shape: WIDE },
  { name: "rainbow", phrase: "a rainbow over green rolling hills after rain", shape: LANDSCAPE },
  { name: "sunflower", phrase: "a sunflower in a terracotta pot", shape: PORTRAIT },
  { name: "cactus", phrase: "a cactus with pink flowers in the desert", shape: PORTRAIT },
  { name: "coffee", phrase: "a cup of coffee next to an open book on a table", shape: SQUARE },
];

/** The seed of subject `index` (the same seed for both generators). */
export const seedOf = (index: number): number => 1000 + index;

/** The caption of a subject: its phrase as a sentence. */
export const captionOf = (subject: Subject): string =>
  `${subject.phrase.charAt(0).toUpperCase()}${subject.phrase.slice(1)}.`;

/**
 * The two image generators. `generator` is the manifest's `<mirror>/<model id>`; `prompt` is
 * written in the style each model was trained on (Anima on tag lists, where `no humans` keeps
 * people out; MOSS-Image on sentences).
 */
export const IMAGE_GENERATORS = {
  anima: {
    mount: "anima",
    mirror: "karume-anima",
    model: "anima-turbo-v1.1",
    prompt: (subject: Subject): string =>
      `no humans, ${subject.phrase}, highly detailed, masterpiece, best quality`,
  },
  moss: {
    mount: "moss-image",
    mirror: "karume-moss-image",
    model: "sft",
    prompt: (subject: Subject): string => `A photo of ${subject.phrase}.`,
  },
} as const;

export type ImageGeneratorName = keyof typeof IMAGE_GENERATORS;

/**
 * The 8 sentences, shortest first: about 1 s to 12 s of speech. Neutral everyday content, with no
 * word whose reading is ambiguous to the analyser.
 */
export const SENTENCES: readonly string[] = [
  "おはようございます。",
  "今日はいい天気ですね。",
  "駅までは歩いて五分ほどです。",
  "冷蔵庫に牛乳と卵が入っています。",
  "明日の会議は午前十時から三階の会議室で始まる予定です。",
  "この公園には大きな池があり、春になると桜の花がたくさん咲きます。",
  "図書館は月曜日が休みなので、本を返すときは火曜日以降に来てください。",
  "朝早く家を出て電車に乗り、二時間ほどかけて山のふもとの小さな町に着きました。そこから川沿いの道をゆっくり歩き、昼過ぎには湖の見える丘の上で休みました。",
];

/** The four SBV2 speakers: the models of the `karume-sbv2-jvnv` mirror. */
export const SPEAKERS = ["F1", "F2", "M1", "M2"] as const;

export type Speaker = (typeof SPEAKERS)[number];

/** The seed of every SBV2 synthesis. */
export const SPEECH_SEED = 0;

/** One image to generate. */
export type PlannedImage = {
  readonly generator: ImageGeneratorName;
  readonly subject: Subject;
  readonly item: ImageItem;
};

/** One clip to synthesise (the sample rate is known only once it is synthesised). */
export type PlannedClip = {
  readonly speaker: Speaker;
  readonly item: Omit<AudioItem, "sampleRate">;
};

export type Plan = {
  readonly images: readonly PlannedImage[];
  readonly audio: readonly PlannedClip[];
};

/**
 * Every file of the set, grouped by generator (each image generator's subjects in table order,
 * then each speaker's sentences shortest first). `limit` keeps the first `limit` items of each
 * generator — of Anima, of MOSS-Image and of each SBV2 speaker — so a smoke run touches every
 * pipeline and every speaker's model.
 */
export const planSet = (limit?: number): Plan => {
  const take = <T>(items: readonly T[]): readonly T[] =>
    limit === undefined ? items : items.slice(0, limit);
  const images = (Object.keys(IMAGE_GENERATORS) as ImageGeneratorName[]).flatMap((generator) => {
    const spec = IMAGE_GENERATORS[generator];
    return take(SUBJECTS).map((subject, index) => ({
      generator,
      subject,
      item: {
        file: `images/${generator}-${subject.name}.png`,
        caption: captionOf(subject),
        generator: `${spec.mirror}/${spec.model}`,
        prompt: spec.prompt(subject),
        seed: seedOf(index),
      },
    }));
  });
  const audio = SPEAKERS.flatMap((speaker) =>
    take(SENTENCES).map((transcript, index) => ({
      speaker,
      item: {
        file: `audio/${speaker}-${String(index + 1).padStart(2, "0")}.wav`,
        transcript,
        generator: `sbv2-jvnv/${speaker}`,
      },
    })),
  );
  return { images, audio };
};

/** A command line the generator cannot act on. */
export class UsageError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "UsageError";
  }
}

export const USAGE =
  "usage: node tools/embeddinggemma2-quality-set/generate.ts [<output directory>] [--limit <n>]";

export type CommandLine = {
  /** `undefined` = the default directory. */
  readonly output: string | undefined;
  /** `undefined` = the whole set. */
  readonly limit: number | undefined;
};

/** Reads `[<output directory>] [--limit <n>]` (also `--limit=<n>`); `n` is a positive integer. */
export const parseCommandLine = (args: readonly string[]): CommandLine => {
  let output: string | undefined;
  let limit: number | undefined;
  const readLimit = (raw: string | undefined): number => {
    if (raw === undefined || !/^[1-9]\d*$/.test(raw)) {
      throw new UsageError(
        `--limit takes a positive integer, not ${JSON.stringify(raw)}\n${USAGE}`,
      );
    }
    return Number(raw);
  };
  for (let at = 0; at < args.length; at += 1) {
    const arg = args[at];
    if (arg === "--limit" || arg.startsWith("--limit=")) {
      if (limit !== undefined) throw new UsageError(`--limit is given twice\n${USAGE}`);
      if (arg === "--limit") {
        at += 1;
        limit = readLimit(args[at]);
      } else {
        limit = readLimit(arg.slice("--limit=".length));
      }
    } else if (arg.startsWith("-")) {
      throw new UsageError(`unknown option ${arg}\n${USAGE}`);
    } else {
      if (output !== undefined) throw new UsageError(`more than one output directory\n${USAGE}`);
      output = arg;
    }
  }
  return { output, limit };
};
